import React from 'react';
import "./Contact.css";
import Swal from 'sweetalert2'

function Contact() {
  const onSubmit = async (event) => {
    event.preventDefault();
    const formData = new FormData(event.target);

    formData.append("access_key", "aff32320-19be-4d5e-b396-b9e151fdcfe6");

    const object = Object.fromEntries(formData);
    const json = JSON.stringify(object);

    const res = await fetch("https://api.web3forms.com/submit", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json"
      },
      body: json
    }).then((res) => res.json());

    if (res.success) {
      Swal.fire({
        title: "Good job!",
        text: "Your message sent successfully!",
        icon: "success"
      });
    }
  };
  return (
    <div className="contact" id='Contacts'>
        <h1 className="page_heading">Contact Me</h1>
        <hr className="line"></hr>
        <div className="about_me">
        <p className='about_text'>I’m always eager to hear about new opportunities and collaborations. If you have any questions, project ideas, or just want to say hello, don’t hesitate to get in touch. You can reach me directly at Email or give me a call at (Contact Number and Email provided below). For more updates on my work, follow me on LinkedIn . Let’s create something amazing together!<br></br><span className='span'>Email</span> : Aryankumar911315@gmail.com
          <br></br><span className='span'>Phone</span> : +91 9113156691 
          <br></br><span className='span'>Instagram-Id</span> :  AryanChoudhary2119
        </p>
        </div>
            <div className="contact_bar">
                <form  onSubmit={onSubmit} className='inputs_box'>
                <p className='git'>GET IN TOUCH</p>
                  <input name='name' placeholder='Your Name' className='name_field' required></input>
                  <input name='email' placeholder='Email' required></input>
                  <textarea name='message' placeholder='Leave your message here..' required></textarea>
                  <button  type='submit' className='Submit_btn'>Submit</button>
                </form> 
            </div>
        </div>
  );
}

export default Contact;