import React from "react";
import './About.css';
import my_dp from '../assets/my_dp.png';

function About(){

    return(
        <div className="About" id="About">
            <h1 className="page_heading">About</h1>
            <hr className="line"></hr>
            <div className="img_field">
               <div className="pic_img">
                <img src={my_dp} className="pic"></img>
               </div> 
             </div>
            <div className="info_container">
             
             <div className="about_me">
                <p className="about_text"> Welcome ! I’m Aryan Choudhary, hailing from the vibrant town of Begusarai in Bihar. I specialize in crafting seamless user experiences as a front-end and backend developer . Currently I'm studing in IIIT Ranchi , pursuing Bachelor of Technology in Computer and Engineering . </p>
             </div>
             
            </div>
        </div>
       
    );
}
export default About;